findings.codeql_raw_query:
/**
 * @name Eval injection in ImageMath
 * @description Tainted user input flowing to eval calls
 * @kind path-problem
 * @problem.severity error
 * @id py/eval-injection-taint
 * @tags security
 *        external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module EvalTaintConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode call |
      call = API::builtin("eval").getACall() and
      sink = call.getArg(0)
    )
  }
}

module EvalTaintFlow = TaintTracking::Global<EvalTaintConfig>;
import EvalTaintFlow::PathGraph

from EvalTaintFlow::PathNode source, EvalTaintFlow::PathNode sink
where EvalTaintFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Eval injection from $@.", source.getNode(), "user input"
